div.script:
(function(){var t=document.getElementById('smb_order_note_text');if(!t||t.getAttribute('data-on')){return;}t.setAttribute('data-on','1');
var ok=document.getElementById('smb_order_note_ok'),K='smb_order_note',timer=null,last=null;
try{var s=JSON.parse(sessionStorage.getItem(K)||'null');if(s&&Date.now()-s.at<10800000){t.value=s.v;}}catch(e){}
function save(){var v=t.value.trim();if(v===last){return;}var fd=new FormData();fd.append('csrf_token',(window.odoo&&odoo.csrf_token)||'');fd.append('x_customer_note',v||' ');
fetch('/website/form/shop.sale.order',{method:'POST',body:fd}).then(function(r){return r.json();}).then(function(j){if(j&&j.id){last=v;ok.style.display=v?'block':'none';}}).catch(function(){});
try{sessionStorage.setItem(K,JSON.stringify({v:t.value,at:Date.now()}));}catch(e){}}
t.addEventListener('input',function(){ok.style.display='none';clearTimeout(timer);timer=setTimeout(save,700);});
t.addEventListener('blur',function(){clearTimeout(timer);save();});
document.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('a,button')){clearTimeout(timer);save();}},true);
if(t.value.trim()){save();}})();
